mapper.select:
select distinct(node_id) as nodeId, node_name as nodeName
from mp_flow_task_task
where scene_id=#{sceneId}

select count(1) from mp_flow_task_task t,mp_flow_flow_info i
where t.flow_id=i.id and t.scene_id=#{sceneId}

    and t.interactive_type = #{interactiveType}


    and t.node_id = #{nodeId}

select t.id as id, t.interactive_type as interactiveType, t.node_name as nodeName, t.node_ip as nodeIp
,t.success_count as successCount, t.error_count as errorCount, t.success_count+t.error_count as totalCount
,t.task_status as taskStatus, i.title as title, t.resource_type as resourceType
,(select duration from mp_flow_pcap where flow_id=i.id) as duration
,(select pcap_size from mp_flow_pcap where flow_id=i.id) as pcapSize
,(select pkt_num from mp_flow_pcap where flow_id=i.id) as pktNum
,(select protocols from mp_flow_pcap where flow_id=i.id) as protocols
from mp_flow_task_task t,mp_flow_flow_info i
where t.flow_id=i.id and t.scene_id=#{sceneId}

    and t.interactive_type = #{interactiveType}


    and t.node_id = #{nodeId}


    limit #{offset}, #{pageSize}
